def heapify(nums):
    for i in range(len(nums) // 2, -1, -1):
        heapify_subtree(nums, i)
def heapify_subtree(nums, i):
    left = 2 * i + 1
    right = 2 * i + 2
    smallest = i
    if left < len(nums) and nums[left] < nums[smallest]:
        smallest = left
    if right < len(nums) and nums[right] < nums[smallest]:
        smallest = right
    if smallest != i:
        nums[smallest], nums[i] = nums[i], nums[smallest]
        heapify_subtree(nums, smallest)

