def lcs_of_three(s1, s2, s3, m, n, o): 
    if (m == 0 or n == 0 or o == 0): 
        return 0
    if (s1[m - 1] == s2[n - 1] and s1[m - 1] == s3[o - 1]): 
        return 1 + lcs_of_three(s1, s2, s3, m - 1, n - 1, o - 1) 
    else: 
        return max(lcs_of_three(s1, s2, s3, m, n - 1, o), lcs_of_three(s1, s2, s3, m - 1, n, o), lcs_of_three(s1, s2, s3, m, n, o - 1))

