def generate_matrix(n):
    result = [[0 for i in range(n)] for j in range(n)]
    i, j, di, dj = 0, 0, 0, 1
    for k in range(n*n):
        result[i][j] = k+1
        i += di
        j += dj
        if i == n:
            di, dj = dj, 0
        elif j == n:
            di, dj = 0, -1
        elif i < 0:
            di, dj = 0, 1
        elif j < 0:
            di, dj = 1, 0
    return result

