def nth_super_ugly_number(n, primes):
    heap = []
    heapq.heappush(heap, (1, 1))
    ugly = 1
    while n > 1:
        ugly, i = heapq.heappop(heap)
        for p in primes:
            heapq.heappush(heap, (ugly * p, i + 1))
        n -= 1
    return ugly

