def combine_lists(l1, l2):
  import heapq
  heap = []
  for i in l1:
    heapq.heappush(heap, i)
  for i in l2:
    heapq.heappush(heap, i)
  result = []
  while heap:
    result.append(heapq.heappop(heap))
  return result

