def subset(nums, n): 
	dp = [[0 for i in range(n + 1)] for j in range(n + 1)] 
	for i in range(n + 1): 
		dp[i][0] = 1
	for i in range(1, n + 1): 
		for j in range(1, n + 1): 
			dp[i][j] = dp[i - 1][j] 
			if nums[i - 1] == nums[j - 1]: 
				dp[i][j] += dp[i - 1][j - 1] 
	return dp[n][n]

